-- Prices supplied by the owner. Original BRL x 1.045, HALF_UP to cents.
-- Absolute upserts make re-runs non-compounding. No customer or order rows changed.
update public.yp_products set active=false,updated_at=now() where sku in ('BAU','CHO','NEU','GRE');
update public.yp_lines set active=false where name in ('Sorvete soft','Iogurte grego');
update public.yp_lines set position=5 where name='Apoio à operação';
